    pq.bar = pq:CreateTexture(nil, "ARTWORK"); pq.bar:SetColorTexture(1, 0.85, 0.45, 1); pq.bar:SetPoint("TOPLEFT", 1, -1); pq.bar:SetPoint("BOTTOMLEFT", 1, 1); pq.bar:SetWidth(4)
