      r.val = fs(pq, "body", 13); r.val:SetPoint("TOPLEFT", 124, -(11 + (i - 1) * 24)); r.val:SetWidth(540); r.val:SetJustifyH("LEFT"); r.val:SetTextColor(0.93, 0.89, 0.78)
