      dim:Show()
    end)
    reveal:HookScript("OnHide", function() dim:Hide() end)
    -- one update loop: the seal pulses, the cards are dealt, the burst fades
    reveal:SetScript("OnUpdate", function(self, dt)
      local t = GetTime and GetTime() or 0
      if self.phase == "seal" then
        if self.holding then
          self.holdT = self.holdT + dt
          local x, y = cursorXY()
          local d = math.sqrt((x - self.hx) ^ 2 + (y - self.hy) ^ 2)
          if d > self.moved then self.moved = d end
          self.tear = math.max(self.tear, math.min(1, math.max(d / 80, (self.holdT - 0.15) / 1.1)))
        else
          self.tear = math.max(0, self.tear - dt * 1.4)
        end
        self.pickIdle = self.pickIdle + dt
        if self.pickIdle > 2 and self.picks > 0 then self.picks = 0 end
        if self.tear >= 1 then tearOpen(); return end
        local tt = math.max(self.tear, self.picks / 3 * 0.85)
        local k = (self.baseK or 1) * (1 + 0.015 * math.sin(t * 3) + 0.10 * tt)
        self.lastK = k
        self.seal:SetScale(k)
        self.seal:ClearAllPoints(); self.seal:SetPoint("CENTER", math.sin(t * 55) * 2 * tt / k, (20 + math.cos(t * 47) * 1.5 * tt + 4 * math.sin(t * 1.4)) / k)
        -- the strip lifts, tilts and pulls away as the tear goes on
        stripSet(self, 1, 14 * tt, 24 * tt, -0.35 * tt, 1)
        -- the sheen: a band that sweeps across, then rests
        local cyc = (t * 0.3) % 1
        local sw = math.min(1, cyc / 0.45)
        local u0 = 0.58 - 0.46 * sw
        self.sheen:SetTexCoord(u0, u0 + 0.35, 0, 1)
        self.sheen:SetAlpha(0.55 * math.sin(math.min(1, sw) * 3.1416) ^ 0.5)
        for i, d in ipairs(self.dashes) do d:SetAlpha(math.max(0, (0.35 + 0.35 * math.sin(t * 3 - i * 0.35)) * (1 - tt * 3))) end
        self.sealHint:SetAlpha(0.65 + 0.3 * math.sin(t * 2.2))
        self.glowTex:SetAlpha(0.26 + 0.06 * math.sin(t * 2) + 0.2 * tt)
        self.sealGlow:SetAlpha(0)
        local c = self.sealCol
        local r, g, b = c[1] + (1 - c[1]) * tt * 0.4, c[2] + (1 - c[2]) * tt * 0.4, c[3] + (1 - c[3]) * tt * 0.4
        self.sealTex:SetVertexColor(r, g, b, 1); self.strip:SetVertexColor(r, g, b, 1); self.glowTex:SetVertexColor(c[1], c[2], c[3], 1); self.sheen:SetVertexColor(1, 1, 1, 1)
        self.spot:SetVertexColor(c[1], c[2], c[3], 0.34 + 0.05 * math.sin(t * 1.7) + 0.12 * tt)
        self.floor:SetVertexColor(c[1], c[2], c[3], 0.5)
      elseif self.phase == "deal" then
        self.dealT = self.dealT + dt
        do local c = self.sealCol; self.spot:SetVertexColor(c[1], c[2], c[3], 0.2) end
        local all = true
        local n = #(self.got or {})
        for i = 1, n do
          local k = math.max(0, math.min(1, (self.dealT - (i - 1) * 0.09) / 0.4))
          local e = 1 - (1 - k) ^ 3
          local x, y, sc, cw = dealPositions(i, n)
          local cx = (RW - cw) / 2
          local c = self.cards[i]
          c:ClearAllPoints(); c:SetPoint("TOPLEFT", self, "TOPLEFT", (cx + (x - cx) * e) / sc, y / sc)
          c:SetAlpha(e)
          if k < 1 then all = false end
        end
        if all then self.phase = false end
      end
      if type(self.sealFade) == "number" and self.sealFade > 0 then
        -- the strip is thrown off and the wrapper drops away
        self.sealFade = self.sealFade - dt
        local k = 1 - math.max(0, self.sealFade) / 0.55
        stripSet(self, 1, 40 + 170 * k, 24 + 140 * k - 190 * k * k, -0.35 - 1.6 * k, 1 - k)
        self.seal:SetAlpha(math.max(0, 1 - k * 1.4))
        self.spot:SetVertexColor(self.sealCol[1], self.sealCol[2], self.sealCol[3], 0.2 + 0.14 * (1 - k))
        if self.sealFade <= 0 then self.sealFade = nil; self.seal:Hide(); self.seal:SetAlpha(1); self.seal:SetScale(1); stripSet(self, 1, 0, 0, 0, 1) end
      end
      if self.shakeT > 0 then
        self.shakeT = self.shakeT - dt
        local m = 3.5 * self.shakeK * math.max(0, self.shakeT) / 0.35
        revealPoint(self, (math.random() - 0.5) * 2 * m, (math.random() - 0.5) * 2 * m)
        if self.shakeT <= 0 then revealPoint(self, 0, 0) end
      end
      if self.shardT > 0 then
        self.shardT = self.shardT - dt
        for _, sh in ipairs(self.shards) do
          sh.vy = sh.vy - 900 * dt; sh.x = sh.x + sh.vx * dt; sh.y = sh.y + sh.vy * dt
          sh.tex:ClearAllPoints(); sh.tex:SetPoint("CENTER", self, "CENTER", sh.x, sh.y)
          sh.tex:SetAlpha(math.max(0, self.shardT / 0.8))
          if self.shardT <= 0 then sh.tex:Hide() end
        end
      end
      if self.burstLeft and self.burstLeft > 0 then
        self.burstLeft = self.burstLeft - dt
        local k = math.max(0, self.burstLeft / self.burstMax)
        self.burst:SetAlpha(k * k)
        self.burstSpin = (self.burstSpin or 0) + dt * 0.5
        if self.burst.SetRotation then self.burst:SetRotation(self.burstSpin) end
        if self.burstLeft <= 0 then self.burst:Hide() end
      end
    end)
  end
  reveal.got, reveal.flipped, reveal.notes, reveal.meta, reveal.record = got, 0, notes, meta, false
  meta = meta or {}
  -- what kind of pack this is: a pack, a jumbo, a super jumbo (a reward pack is a jumbo with extra promises), or several at once
  local kind = (meta.kind and PACKS[meta.kind]) and meta.kind or "normal"
  local def = PACKS[kind]
  reveal.kind = kind
  local col, title, info = def.col, def.name, {}
  if meta.gift then
    col, title = { 1, 0.85, 0.45 }, "Level 60 gift"
    info[#info + 1] = { "Your gift", GOLDHEX .. "Three cards rated 105 or higher|r" }
    info[#info + 1] = { "Also", "5 packs, 5 jumbo packs and 5 super jumbo packs are waiting for you" }
  elseif meta.bonus then
    col, title = { 0.85, 0.6, 1 }, "Reward Jumbo Pack"
    info[#info + 1] = { "Reward pack", "|cffd9a8ff" .. def.size .. " cards: two rares and a holo or better inside|r" }
  elseif meta.many then
    col, title = { 1, 0.85, 0.45 }, meta.many.count .. " packs"
    info[#info + 1] = { "Packs", GOLDHEX .. meta.many.count .. " packs at once|r   ·   the five best cards are shown" }
  else
    info[#info + 1] = { "Contents", GOLDHEX .. def.size .. " cards|r from the whole collection   ·   " .. def.rares .. " rare or better" }
    if meta.daily then title = "Daily " .. def.name; info[#info + 1] = { "Daily", "|cff7be08aDay " .. (meta.streak or 1) .. " in a row|r" } end
  end
  if not meta.many and not meta.gift then
    local pb = meta.pityBefore or 0
